-- NUERS reporting queue only. Existing application user remains the definer.
USE `NUERS`;
DELIMITER $$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_rece_insert AFTER INSERT ON transaction_receipts FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',NEW.id,1 FROM DUAL WHERE NEW.id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'transaction',id,1 FROM merchant_transactions WHERE receipt_id=NEW.id AND merchant_id=NEW.merchant_id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_rece_update AFTER UPDATE ON transaction_receipts FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',OLD.id,1 FROM DUAL WHERE OLD.id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'transaction',id,1 FROM merchant_transactions WHERE receipt_id=OLD.id AND merchant_id=OLD.merchant_id ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',NEW.id,1 FROM DUAL WHERE NEW.id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'transaction',id,1 FROM merchant_transactions WHERE receipt_id=NEW.id AND merchant_id=NEW.merchant_id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_rece_delete AFTER DELETE ON transaction_receipts FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',OLD.id,1 FROM DUAL WHERE OLD.id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'transaction',id,1 FROM merchant_transactions WHERE receipt_id=OLD.id AND merchant_id=OLD.merchant_id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
